// ---- strip ------------------------------------------------------------
function buildCard(candidate) {
  const card = el('div', 'ri-card');
  card.dataset.key = candidate.key;
  card.setAttribute('role', 'option');
  const entry = { card, image: null, imageUrl: null };
  entry.thumb = el('div', 'ri-thumb', card);
